seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
comp = {'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return "".join(comp[c] for c in reversed(s))
stops={'TAA','TAG','TGA'}

def orfs(s):
    res=[]
    for strand in (1,-1):
        t = s if strand==1 else rc(s)
        for f in range(3):
            i=f
            start=None
            while i < len(t)-2:
                cod=t[i:i+3]
                if start is None:
                    if cod=='ATG':
                        start=i
                else:
                    if cod in stops:
                        res.append((start,i+3,strand,f))
                        start=None
                i+=3
    return res

o=orfs(seq)
o.sort(key=lambda x:-(x[1]-x[0]))
for a,b,st,f in o[:15]:
    print("strand",st,"frame",f,"len_aa",(b-a)//3-1, "coords(1-based, fwd)", (a+1,b) if st==1 else (len(seq)-b+1,len(seq)-a))
