seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
import re
L=len(seq)
# tandem repeats period 1-6, unit repeated >=3 times (or >=12bp)
def find_tandem(s):
    out=[]
    for p in range(1,7):
        for start in range(len(s)-p*3+1):
            unit=s[start:start+p]
            n=1
            i=start+p
            while s[i:i+p]==unit:
                n+=1; i+=p
            if n>=3 and n*p>=12:
                out.append((start+1,start+n*p,unit,n))
    # dedupe
    seen=set(); res=[]
    for o in sorted(out):
        if (o[0],o[1]) not in seen:
            seen.add((o[0],o[1])); res.append(o)
    return res
for o in find_tandem(seq):
    print("tandem", o)

