def tm(p,win=19,thr=1.6):
    out=[]
    for i in range(len(p)-win+1):
        s=sum(kd[p[j]] for j in range(i,i+win))/win
        if s>thr: out.append(i+1)
    # group
    groups=[]
    for x in out:
        if groups and x-groups[-1][-1]<=3: groups[-1].append(x)
        else: groups.append([x])
    return [(g[0],g[-1]+win-1) for g in groups]
