import random
seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
comp={'A':'T','T':'A','G':'C','C':'G'}
rc=lambda s:"".join(comp[c] for c in reversed(s))
stops={'TAA','TAG','TGA'}
def longest_orf_len(s):
    best=0
    for f in range(3):
        i=f; run=0
        while i<=len(s)-3:
            if s[i:i+3] in stops:
                run=0
            else:
                run+=1
                best=max(best,run)
            i+=3
    return best
def max_orf_both(s):
    return max(longest_orf_len(s), longest_orf_len(rc(s)))

print("real sequence longest ORF (codons, either strand):", max_orf_both(seq))

# shuffle the whole sequence (mono) and also each half separately
random.seed(1)
bases=list(seq)
N=500
dall=[]
for _ in range(N):
    random.shuffle(bases)
    dall.append(max_orf_both("".join(bases)))
dall.sort()
print("shuffled whole-seq longest ORF: median", dall[N//2], "95th pct", dall[int(0.95*N)], "max", dall[-1])

# shuffle GC-rich half only
for lo,hi,label in [(0,800,"AT-rich 1-800"),(800,3000,"GC-rich 801-3000")]:
    sub=list(seq[lo:hi]); res=[]
    for _ in range(N):
        random.shuffle(sub); res.append(max_orf_both("".join(sub)))
    res.sort()
    print(label,"len",hi-lo,"-> shuffled longest ORF median",res[N//2],"95pct",res[int(0.95*N)],"max",res[-1],
          "| observed", max_orf_both(seq[lo:hi]))
"}
